package com.bank.autoscale.hpa;

import java.util.logging.Logger;

// HPA: change REPLICA COUNT to drive CPU toward a target.
public class HorizontalPodAutoscaler {
    private static final Logger log = Logger.getLogger(HorizontalPodAutoscaler.class.getName());
    private final int min, max, targetCpuPercent;
    private int replicas;

    public HorizontalPodAutoscaler(int min, int max, int targetCpuPercent) {
        this.min = min; this.max = max; this.targetCpuPercent = targetCpuPercent;
        this.replicas = min;
    }

    // desiredReplicas = ceil(currentReplicas * currentCpu / targetCpu)
    public int reconcile(int currentCpuPercent) {
        int desired = (int) Math.ceil(replicas * (double) currentCpuPercent / targetCpuPercent);
        desired = Math.max(min, Math.min(max, desired));
        if (desired != replicas) {
            int from = replicas, to = desired;
            log.info(() -> "HPA cpu=" + currentCpuPercent + "% target=" + targetCpuPercent
                    + "% replicas " + from + " -> " + to);
            replicas = desired;
        }
        return replicas;
    }
    public int getReplicas() { return replicas; }
}
