package com.bank.autoscale.vpa;

import java.util.logging.Logger;

// VPA: recommend better CPU/memory REQUESTS per pod (recommendation mode).
public class VerticalPodAutoscaler {
    private static final Logger log = Logger.getLogger(VerticalPodAutoscaler.class.getName());
    private int recommendedMemoryMi;

    // Observe actual usage and recommend a size (does NOT act on CPU => no HPA fight).
    public int recommendMemory(int observedPeakMemoryMi) {
        // Recommend peak + 20% headroom, rounded to 128Mi steps.
        int withHeadroom = (int) (observedPeakMemoryMi * 1.2);
        recommendedMemoryMi = ((withHeadroom + 127) / 128) * 128;
        log.info(() -> "VPA observed peak mem=" + observedPeakMemoryMi
                + "Mi -> recommend request=" + recommendedMemoryMi + "Mi (requires pod recreate)");
        return recommendedMemoryMi;
    }
    public int getRecommendedMemoryMi() { return recommendedMemoryMi; }
}
