package com.bank.autoscale.cluster;

import java.util.logging.Logger;

// Cluster Autoscaler: add NODES when pods are pending; remove idle nodes.
public class ClusterAutoscaler {
    private static final Logger log = Logger.getLogger(ClusterAutoscaler.class.getName());
    private final int podsPerNode;
    private int nodes;

    public ClusterAutoscaler(int startingNodes, int podsPerNode) {
        this.nodes = startingNodes; this.podsPerNode = podsPerNode;
    }

    // Given total pods that must run, ensure enough nodes exist.
    public int reconcile(int totalPods) {
        int capacity = nodes * podsPerNode;
        if (totalPods > capacity) {
            int needed = (int) Math.ceil((double) totalPods / podsPerNode);
            int from = nodes, to = needed;
            log.warning(() -> "CLUSTER pending pods: " + (totalPods - capacity)
                    + " -> add nodes " + from + " -> " + to);
            nodes = needed;
        } else if (totalPods <= (nodes - 1) * podsPerNode && nodes > 1) {
            int from = nodes, to = nodes - 1;
            log.info(() -> "CLUSTER node idle -> remove nodes " + from + " -> " + to);
            nodes = nodes - 1;
        }
        return nodes;
    }
    public int getNodes() { return nodes; }
}
