package com.bank.autoscale.keda;

import java.util.logging.Logger;

// KEDA: scale workers by QUEUE DEPTH (not CPU), including scale-to-zero.
public class KedaScaler {
    private static final Logger log = Logger.getLogger(KedaScaler.class.getName());
    private final int lagThreshold;   // messages per worker
    private final int maxReplicas;
    private int replicas = 0;         // starts at ZERO

    public KedaScaler(int lagThreshold, int maxReplicas) {
        this.lagThreshold = lagThreshold; this.maxReplicas = maxReplicas;
    }

    // currentLag = unprocessed messages / Kafka consumer-group lag.
    public int reconcile(int currentLag) {
        int desired = currentLag == 0 ? 0
                : Math.min(maxReplicas, (int) Math.ceil((double) currentLag / lagThreshold));
        if (desired != replicas) {
            int from = replicas, to = desired;
            String note = (from == 0 && to > 0) ? " (wake from ZERO)"
                    : (to == 0 ? " (scale to ZERO - no work)" : "");
            log.info(() -> "KEDA lag=" + currentLag + " workers " + from + " -> " + to + note);
            replicas = desired;
        }
        return replicas;
    }
    public int getReplicas() { return replicas; }
}
