package com.bank.autoscale;

import com.bank.autoscale.cluster.ClusterAutoscaler;
import com.bank.autoscale.hpa.HorizontalPodAutoscaler;
import com.bank.autoscale.keda.KedaScaler;
import com.bank.autoscale.vpa.VerticalPodAutoscaler;
import java.util.logging.*;

public class AutoscaleDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
        Logger log = Logger.getLogger(AutoscaleDemo.class.getName());

        // HPA: transfer API scales replicas on CPU.
        log.info("=== HPA (replicas by CPU) ===");
        HorizontalPodAutoscaler hpa = new HorizontalPodAutoscaler(3, 30, 60);
        hpa.reconcile(90);   // hot -> scale out
        hpa.reconcile(30);   // cool -> scale in

        // VPA: recommends memory (different dimension) -> does NOT fight HPA.
        log.info("=== VPA (pod size, recommendation only) ===");
        VerticalPodAutoscaler vpa = new VerticalPodAutoscaler();
        vpa.recommendMemory(700);  // observed peak 700Mi

        // KEDA: settlement worker scales on QUEUE DEPTH, from zero.
        log.info("=== KEDA (workers by queue depth, scale-to-zero) ===");
        KedaScaler keda = new KedaScaler(500, 50);
        keda.reconcile(0);      // quiet -> zero workers
        keda.reconcile(10000);  // market close backlog -> wake and scale up
        keda.reconcile(0);      // drained -> back to zero

        // Cluster Autoscaler: add nodes when all those pods can't fit.
        log.info("=== Cluster Autoscaler (nodes for pending pods) ===");
        ClusterAutoscaler cluster = new ClusterAutoscaler(3, 10); // 3 nodes, 10 pods each
        int totalPods = hpa.getReplicas() + keda.getReplicas() + 20; // mix of workloads
        cluster.reconcile(totalPods);

        log.info("Summary: HPA replicas=" + hpa.getReplicas()
                + ", VPA mem=" + vpa.getRecommendedMemoryMi() + "Mi"
                + ", KEDA workers=" + keda.getReplicas()
                + ", nodes=" + cluster.getNodes());
    }
}

